package com.ashkan.hotel;

import java.math.BigDecimal;import java.sql.*;import java.util.*;
public final class PaymentRepository extends JdbcDomainRepository {
 public record Payment(String id,String bookingId,BigDecimal amount,String currency,String method,String status,String providerReference){public Payment{req(id);req(bookingId);if(amount==null||amount.signum()<=0)throw new IllegalArgumentException("amount must be positive");currency=Objects.requireNonNullElse(currency,"EUR").toUpperCase(Locale.ROOT);if(!currency.matches("[A-Z]{3}"))throw new IllegalArgumentException("Invalid currency");req(method);status=Objects.requireNonNullElse(status,"INITIATED").toUpperCase(Locale.ROOT);if(!Set.of("INITIATED","AUTHORIZED","CAPTURED","FAILED","REFUNDED").contains(status))throw new IllegalArgumentException("Invalid payment status");}}
 private final TtlCache<String,Optional<Payment>> cache=new TtlCache<>(CacheSettings.ttlMillis(),CacheSettings.maxEntries()); private final RedisCacheClient redis=new RedisCacheClient(); private String redisKey(String id){return "hotelsphere:payment:"+id;}
 public PaymentRepository(String u,String n,String p,int z){super(u,n,p,z);}
 public void save(Payment x)throws SQLException{withConnection(c->{try(PreparedStatement p=c.prepareStatement("INSERT INTO payment_transactions(transaction_id,booking_id,amount,currency,method,status,provider_reference) VALUES(?,?,?,?,?,?,?) ON CONFLICT(transaction_id) DO UPDATE SET booking_id=EXCLUDED.booking_id,amount=EXCLUDED.amount,currency=EXCLUDED.currency,method=EXCLUDED.method,status=EXCLUDED.status,provider_reference=EXCLUDED.provider_reference,updated_at=NOW()")){p.setString(1,x.id());p.setString(2,x.bookingId());p.setBigDecimal(3,x.amount());p.setString(4,x.currency());p.setString(5,x.method());p.setString(6,x.status());p.setString(7,x.providerReference());p.executeUpdate();}return null;});cache.invalidate(x.id());redis.delete(redisKey(x.id()));}
 public Optional<Payment> find(String id)throws SQLException{Optional<Payment> cached=cache.get(id);if(cached!=null)return cached;String remote=redis.get(redisKey(id));if(remote!=null){try{String[] a=CacheCodec.unpack(remote,7);Optional<Payment> value=Optional.of(new Payment(a[0],a[1],new BigDecimal(a[2]),a[3],a[4],a[5],a[6]));cache.put(id,value);return value;}catch(RuntimeException ignored){redis.delete(redisKey(id));}}Optional<Payment> result=withConnection(c->{try(PreparedStatement p=c.prepareStatement("SELECT * FROM payment_transactions WHERE transaction_id=?")){p.setString(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(new Payment(r.getString("transaction_id"),r.getString("booking_id"),r.getBigDecimal("amount"),r.getString("currency"),r.getString("method"),r.getString("status"),r.getString("provider_reference"))):Optional.empty();}}});cache.put(id,result);result.ifPresent(x->redis.set(redisKey(id),CacheCodec.pack(x.id(),x.bookingId(),x.amount().toPlainString(),x.currency(),x.method(),x.status(),x.providerReference()),(int)Math.max(1,CacheSettings.ttlMillis()/1000)));return result;}
 public List<Payment> list(int limit,int offset,String status)throws SQLException{return withConnection(c->{String sql="SELECT * FROM payment_transactions"+(status==null||status.isBlank()?"":" WHERE status=?")+" ORDER BY created_at DESC LIMIT ? OFFSET ?";try(PreparedStatement p=c.prepareStatement(sql)){int i=1;if(status!=null&&!status.isBlank())p.setString(i++,status.toUpperCase(Locale.ROOT));p.setInt(i++,limit);p.setInt(i,offset);try(ResultSet r=p.executeQuery()){List<Payment> out=new ArrayList<>();while(r.next())out.add(new Payment(r.getString("transaction_id"),r.getString("booking_id"),r.getBigDecimal("amount"),r.getString("currency"),r.getString("method"),r.getString("status"),r.getString("provider_reference")));return out;}}});}
 public void updateStatus(String id,String status,String providerReference)throws SQLException{String normalized=Objects.requireNonNull(status).toUpperCase(Locale.ROOT);if(!Set.of("INITIATED","AUTHORIZED","CAPTURED","FAILED","REFUNDED").contains(normalized))throw new IllegalArgumentException("Invalid payment status");withConnection(c->{try(PreparedStatement p=c.prepareStatement("UPDATE payment_transactions SET status=?,provider_reference=COALESCE(?,provider_reference),updated_at=NOW() WHERE transaction_id=?")){p.setString(1,normalized);p.setString(2,providerReference);p.setString(3,id);if(p.executeUpdate()!=1)throw new SQLException("Payment not found");}return null;});cache.invalidate(id);redis.delete(redisKey(id));}
 public void delete(String id)throws SQLException{withConnection(c->{try(PreparedStatement p=c.prepareStatement("DELETE FROM payment_transactions WHERE transaction_id=?")){p.setString(1,id);p.executeUpdate();}return null;});cache.invalidate(id);redis.delete(redisKey(id));}
 private static void req(String s){if(s==null||s.isBlank())throw new IllegalArgumentException("Required payment field missing");}
}
